// Same defensive unwrap as AZkGM5M4c1uzSH7S 'Normalise Dealership List' (NX1000 wave): nexus_active_dealership_ids() returns setof uuid, PostgREST wraps it as an array of {nexus_active_dealership_ids: <uuid>} objects, but this also accepts a bare uuid string per item and the whole-array-in-one-item shape some HTTP node versions hand back.
const UUID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;
function extract(v) {
  if (typeof v === 'string') return v;
  if (v && typeof v === 'object') {
    if (typeof v.nexus_active_dealership_ids === 'string') return v.nexus_active_dealership_ids;
    const only = Object.values(v).find(x => typeof x === 'string' && UUID.test(x));
    if (only) return only;
  }
  return null;
}
let raw = $input.all().map(i => i.json);
if (raw.length === 1 && Array.isArray(raw[0])) raw = raw[0];
const ids = raw.map(extract).filter(id => id && UUID.test(id));
return ids.map(id => ({ json: { tenant_id: id } }));

// nexus_pending_scoring_leads_for_tenant returns one row per lead. Reshape to the same { lead, attempt: -1 } envelope 'Model Ladder' (in the Master Lead Router, JnlZFAVmFAuNXVya) already expects, so 'Rescore Model Ladder' below can reuse that exact tier logic unmodified.
let rows = $input.all().map(i => i.json);
if (rows.length === 1 && Array.isArray(rows[0])) rows = rows[0];
return rows
  .filter(r => r && r.id != null && r.tenant_id)
  .map(r => ({ json: {
    lead_id: r.id,
    tenant_id: r.tenant_id,
    scoring_attempts: r.scoring_attempts || 0,
    attempt: -1,
    lead: {
      name: r.name, email: r.email, phone: r.phone,
      vehicle_interest: r.vehicle_interest, budget_aed: r.budget_aed,
      source: r.source, tenant_id: r.tenant_id
    }
  } }));

// Tier table copied from the Master Lead Router (JnlZFAVmFAuNXVya) node 'Model Ladder' -- keep the two in sync by hand; NX1002 did not extract a shared sub-workflow for this because n8n has no code-sharing primitive that survives 'n8n is read-only for this task'. See that node's own comments (16/29/30 Aug 2026) for why each tier id is what it is.
const GROQ_FALLBACK = 'openai/gpt-oss-120b';
const TIERS = [
  { orModel: 'nvidia/nemotron-3.5-lightning:free',     groqModel: GROQ_FALLBACK },
  { orModel: 'nvidia/nemotron-3-super-120b-a12b:free', groqModel: GROQ_FALLBACK },
  { orModel: 'minimax/minimax-m2.7:free',              groqModel: GROQ_FALLBACK }
];

const prev = $input.first().json;
const attempt = Number(prev.attempt ?? -1) + 1;

if (attempt >= TIERS.length) {
  // NX1002: the router's equivalent node THROWS here, which used to be fatal to the whole execution because nothing set onError on it (exec 16069, 16072). This node has onError=continueErrorOutput, so an uncaught throw here would already be safe for the SWEEP AS A WHOLE (only this lead's branch dies) -- but we still want scoring_attempts incremented and scoring_last_error set for a human to see, not just a silently-dropped item. So this branch RETURNS (does not throw) a small marker item instead, which 'Route: Exhausted?' below sends to 'Record Scoring Result (Failure)'.
  return [{ json: { exhausted: true, lead_id: prev.lead_id, tenant_id: prev.tenant_id, lead: prev.lead, error: 'All ' + TIERS.length + ' free-tier model tiers failed for lead ' + ((prev.lead && prev.lead.email) || prev.lead_id || 'unknown') + '. Tried: ' + TIERS.map(t => t.orModel + ' / ' + t.groqModel).join(', ') } }];
}

return [{ json: {
  exhausted: false,
  lead_id: prev.lead_id, tenant_id: prev.tenant_id, lead: prev.lead,
  attempt, maxTiers: TIERS.length,
  orModel: TIERS[attempt].orModel, groqModel: TIERS[attempt].groqModel
} }];

// Same extractJson/prose-fallback logic as the Master Router's 'Parse AI Decision' -- kept byte-identical on purpose, same reasoning as 'Rescore Model Ladder' above.
const src = $('Rescore Model Ladder').first().json;
const rawOut = $input.first().json;
const text = String(rawOut.output ?? rawOut.text ?? '').trim();

function extractJson(s) {
  if (!s) return null;
  try { return JSON.parse(s); } catch (e) {}
  const fenced = s.replace(/```(?:json)?/gi, '').trim();
  try { return JSON.parse(fenced); } catch (e) {}
  const first = fenced.indexOf('{');
  const last = fenced.lastIndexOf('}');
  if (first !== -1 && last > first) {
    try { return JSON.parse(fenced.slice(first, last + 1)); } catch (e) {}
  }
  return null;
}

let parsed = extractJson(text);
if (!parsed || typeof parsed !== 'object') {
  const intentMatch = text.match(/\b(HOT|WARM|COLD)\b/i);
  const scoreMatch = text.match(/\b(\d{1,3})\b/);
  parsed = {
    intent: intentMatch ? intentMatch[1].toUpperCase() : 'WARM',
    score: scoreMatch ? Math.min(100, parseInt(scoreMatch[1], 10)) : 50,
    reason: 'Agent did not return valid JSON. Raw output: ' + text.substring(0, 300)
  };
}

const rawBudget = Number(parsed.budget_aed);
const budget_aed = Number.isFinite(rawBudget) && rawBudget > 0 ? Math.round(rawBudget) : null;
const intent = String(parsed.intent || '').toUpperCase();

return [{ json: {
  lead_id: src.lead_id, tenant_id: src.tenant_id,
  ai_decision: {
    intent: ['HOT', 'WARM', 'COLD'].includes(intent) ? intent : 'WARM',
    score: Number.isFinite(Number(parsed.score)) ? Number(parsed.score) : 50,
    budget_aed
  }
} }];
